INSERT INTO `nn_buildings` VALUES (1,'RIVERSIDE','NNland Riverside','TP. Hồ Chí Minh','TP. Thủ Đức','Đường Mai Chí Thọ, khu đô thị Thủ Thiêm','Không gian sống hiện đại bên sông, kết nối nhanh đến trung tâm và các tiện ích đô thị.','/nnland/images/building-riverside.webp','Hồ bơi|Phòng gym|Vườn trên cao|An ninh 24/7',1,'2026-11-12 00:30:01'),(2,'CENTRAL','NNland Central Park','TP. Hồ Chí Minh','Bình Thạnh','Khu vực Tân Cảng, Bình Thạnh','Căn hộ tiện nghi cạnh công viên, dành cho nhịp sống năng động giữa thành phố.','/nnland/images/building-central.webp','Công viên|Phòng gym|Siêu thị|Bãi đỗ xe',1,'2026-11-12 00:30:01'),(3,'WESTLAKE','NNland West Lake','Hà Nội','Tây Hồ','Đường Võ Chí Công, Tây Hồ','Nhịp sống yên bình gần hồ Tây với không gian rộng và nhiều ánh sáng tự nhiên.','/nnland/images/building-westlake.webp','Hồ bơi|Café|Khu vui chơi|An ninh 24/7',1,'2026-11-12 00:30:01'),(4,'OCEAN','NNland Ocean View','Đà Nẵng','Sơn Trà','Khu vực đường Võ Nguyên Giáp, Sơn Trà','Không gian sống thoáng sáng gần biển, phù hợp với gia đình và chuyên gia làm việc tại Đà Nẵng.','/nnland/images/amenity-pool.webp','Gần biển|Hồ bơi|Bãi đỗ xe|Sảnh lễ tân',1,'2026-11-12 00:30:01'),(5,'GARDEN','NNland Garden','TP. Hồ Chí Minh','Quận 7','Khu đô thị Phú Mỹ Hưng, Quận 7','Môi trường sống xanh với tiện ích nội khu và không gian riêng tư cho gia đình trẻ.','/nnland/images/lobby.webp','Vườn nội khu|Phòng gym|An ninh 24/7|Khu vui chơi',1,'2026-11-12 00:30:01'),(6,'BADINH','NNland Ba Đình','Hà Nội','Ba Đình','Khu vực Giảng Võ, Ba Đình','Tòa nhà ngay khu vực trung tâm, thuận tiện di chuyển đến các khu văn phòng và điểm đến văn hóa.','/nnland/images/building-westlake.webp','Sảnh lễ tân|Thang máy|Bãi đỗ xe|Café',1,'2026-11-12 00:30:01');

