INSERT INTO `nn_settings` VALUES ('bank_account','','2026-11-12 00:30:00'),('bank_bin','','2026-11-12 00:30:00'),('bank_name','','2026-11-12 00:30:00'),('bank_owner','','2026-11-12 00:30:00'),('contact_email','hello@nnland.vn','2026-11-12 00:30:00'),('hold_minutes','30','2026-11-12 00:30:00'),('hotline','1900 6868','2026-11-12 00:30:00'),('office_address','46 Man Thiện, TP. Hồ Chí Minh','2026-11-12 00:30:00'),('terms_text','NNland cho thuê nguyên căn. Khách thanh toán trước toàn bộ tiền thuê theo số tháng đã chọn. Điện, nước và phí dịch vụ thanh toán theo hóa đơn riêng. Việc giữ chỗ có thời hạn; đơn thuê chỉ được xác nhận sau khi quản lý đối chiếu tiền thực nhận. Hợp đồng được ký trực tiếp khi bàn giao. Gia hạn cần kiểm tra lịch trống và thanh toán trước. Hủy, trả sớm và hoàn tiền được hai bên xác nhận bằng văn bản; tiền cọc được quyết toán khi trả phòng.','2026-11-12 00:30:00'),('terms_version','NN-2026-01','2026-11-12 00:30:00');
